}

.savings-badge {
  display: inline-block;
  padding: 6px 14px;
  background: var(--success);
  color: var(--white);
  font-size: 13px;
  font-weight: 700;
  border-radius: var(--radius-sm);
  margin-bottom: 16px;
}

/* PLUS CAROUSEL */
.plus-carousel-section {
  padding: 64px 0;
}

.plus-carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  padding: 0 24px;
}

.plus-carousel-title {
  font-size: 24px;
  font-weight: 700;
}

/* CREDITS SECTION */
.credits-section {
  padding: 80px 0;
  background: var(--gray-50);
}

.credits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 1000px;
  margin: 0 auto;
}

.credit-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  border: 1px solid var(--gray-100);
}

.credit-card-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 16px;
  background: var(--accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
}

.credit-card-icon svg {
  width: 32px;
  height: 32px;
  color: var(--foreground);
}

.credit-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
}

.credit-card p {
  font-size: 14px;
  color: var(--gray-600);
  line-height: 1.6;
}

/* FAQ ACCORDION */
.faq-section {
  padding: 80px 0;
  max-width: 800px;
  margin: 0 auto;
}

.faq-title {
  font-size: 36px;
  font-weight: 800;
  text-align: center;
  margin-bottom: 48px;
  letter-spacing: -1px;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
