}

.social-btn:hover {
  background: var(--gray-50);
  border-color: var(--gray-300);
}

.social-btn svg {
  width: 20px;
  height: 20px;
}

.login-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-group label {
  font-size: 14px;
  font-weight: 500;
}

.form-group input {
  padding: 12px 16px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  font-size: 15px;
  transition: var(--transition);
}

.form-group input:focus {
  outline: none;
  border-color: var(--foreground);
  box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.05);
}

.password-wrapper {
  position: relative;
}

.password-wrapper input {
  width: 100%;
  padding-right: 44px;
}

.password-toggle {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  padding: 4px;
}

.password-toggle:hover {
  color: var(--gray-600);
}

.form-options {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 14px;
}

.forgot-link {
  color: var(--primary);
  font-weight: 500;
}

.forgot-link:hover {
  text-decoration: underline;
}

.login-submit {
  width: 100%;
  padding: 14px;
  font-size: 15px;
  font-weight: 600;
}

.login-footer {
  text-align: center;
  margin-top: 24px;
  font-size: 14px;
  color: var(--gray-500);
}

.login-footer a {
  color: var(--primary);
  font-weight: 600;
}

.login-footer a:hover {
  text-decoration: underline;
}

/* MOBILE RESPONSIVE */
@media (max-width: 1024px) {
  .value-props-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .courses-layout {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
    display: none;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
    max-width: 400px;
  }
}

@media (max-width: 768px) {
  .header-top {
    padding: 12px 16px;
  }

  .nav-main {
    display: none;
  }

  .search-box {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .hero-slide {
    flex-direction: column;
    text-align: center;
    gap: 24px;
    padding: 0 16px;
  }

  .hero-content {
    max-width: 100%;
  }

  .hero-title {
    font-size: 28px;
  }

  .hero-meta {
    justify-content: center;
  }

  .hero-price {
    justify-content: center;
  }

  .hero-image {
    max-width: 100%;
  }

  .hero-nav {
    margin-top: 24px;
  }

  .carousel-nav {
    display: none;
  }

  .value-props-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .projects-header h1 {
    font-size: 28px;
  }

  .filter-bar {
    flex-direction: column;
    align-items: flex-start;
  }

  .plus-hero h1 {
    font-size: 36px;
  }

  .pricing-toggle {
    flex-direction: column;
    gap: 8px;
  }

  .pricing-card {
    padding: 24px;
  }

  .pricing-amount .price {
    font-size: 36px;
  }

  .login-card {
    padding: 24px;
  }
}

/* Footer accordion for mobile */
@media (max-width: 768px) {
  .footer-col {
    border-bottom: 1px solid var(--gray-200);
    padding-bottom: 16px;
  }

  .footer-col h4 {
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .footer-col h4::after {
    content: '+';
    font-size: 20px;
    font-weight: 300;
  }

  .footer-col.expanded h4::after {
    content: '−';
  }

  .footer-col ul {
    display: none;
    padding-top: 12px;
  }

  .footer-col.expanded ul {
    display: block;
  }
}

